import{_ as a,o as e,c as r,a5 as s}from"./chunks/framework.BZzouRtU.js";const i="/study/images/graphics/input-to-display-latency.svg",g=JSON.parse('{"title":"入力から画面に出るまでの遅延","description":"","frontmatter":{"title":"入力から画面に出るまでの遅延","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"入力を読んだ時点から画面の対象位置が更新されるまでを追い、入力待ち、CPU・GPUの処理と待ち、表示待ちを分けて調べる。","aliases":["入力遅延","input latency","input-to-photon","click-to-photon","ポーリング","レンダーキュー","scanout","入力マーカー"]}},"headers":[],"relativePath":"graphics/optimization/input-to-display-latency.md","filePath":"graphics/optimization/input-to-display-latency.md"}'),n={name:"graphics/optimization/input-to-display-latency.md"};function o(l,t,d,m,p,c){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="入力から画面に出るまでの遅延" tabindex="-1">入力から画面に出るまでの遅延 <a class="header-anchor" href="#入力から画面に出るまでの遅延" aria-label="Permalink to &quot;入力から画面に出るまでの遅延&quot;">​</a></h1><p>クリックして発射しても、同じ瞬間に発射の絵が出るわけではありません。入力機器とOSからゲームに情報が届き、ゲームが入力を反映した状態を作り、GPUが描き、ディスプレイがその絵を読み出します。<strong>入力遅延</strong>を測るときは、「マウスを押した瞬間」「OSが受け取った時刻」「ゲームが入力を読んだ時刻」のどこを始点にするかを決めます。画面上の変化を光として検知する場合は、測る位置と検知条件も終点の一部です。<a href="https://developer.nvidia.com/blog/understanding-and-measuring-pc-latency/" target="_blank" rel="noreferrer">NVIDIAのPC遅延とシステム遅延の解説</a></p><h2 id="一つの入力が画面に出るまでを追う" tabindex="-1">一つの入力が画面に出るまでを追う <a class="header-anchor" href="#一つの入力が画面に出るまでを追う" aria-label="Permalink to &quot;一つの入力が画面に出るまでを追う&quot;">​</a></h2><figure class="study-figure"><img src="'+i+'" alt="入力が7 msに届き、ゲームが8 msに読み、CPU処理が10 msに終わる。GPUは3 ms待って13 msに開始し、17 msに描き終える。16.67 msの走査開始には間に合わず、33.33 msに走査を始め、画面中央に41.67 msで到達する。" width="760" height="312" loading="lazy"><figcaption>一つの入力を追う仮想60 Hzの例。処理中の区間と、処理を始められるまでの待ちを分けています。<a href="/study/images/graphics/input-to-display-latency.svg" target="_blank" rel="noopener noreferrer">タイムラインを拡大</a></figcaption></figure><table tabindex="0"><thead><tr><th>区間</th><th>調べるときに見るもの</th></tr></thead><tbody><tr><td>入力が届く → ゲームが読む</td><td>次に入力を読む機会、イベントの処理、入力を使うシミュレーションの刻み</td></tr><tr><td>入力を読む → GPUへ仕事を渡す</td><td>CPU上のゲーム更新、描画コマンドの準備、スレッド間の待ち</td></tr><tr><td>GPUへ仕事を渡す → 描画完了</td><td>GPUが処理を始めるまでの待ち、描画やコピーにかかった時間</td></tr><tr><td>描画完了 → 表示が始まる</td><td>提示待ち、次の走査開始時刻、OSの合成や提示方式</td></tr><tr><td>表示が始まる → 対象位置が変わる</td><td>走査がその位置に到達する時間、画素の応答</td></tr></tbody></table><p>同じフレームのCPU処理とGPU処理だけを足すと、処理を待っている区間が抜けます。一方、複数のフレームの仕事は並行するので、タイムライン全体のCPU・GPU時間の合計も、ある入力の遅延を表す値にはなりません。入力に番号を付け、その入力を使った更新・描画・提示を対応付けます。<a href="/study/graphics/optimization/gpu-timestamp-queries.html">GPU時間をタイムスタンプで測る</a> · <a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a></p><h2 id="_2-msの待ちが、表示時刻を約16-67-ms動かす例" tabindex="-1">2 msの待ちが、表示時刻を約16.67 ms動かす例 <a class="header-anchor" href="#_2-msの待ちが、表示時刻を約16-67-ms動かす例" aria-label="Permalink to &quot;2 msの待ちが、表示時刻を約16.67 ms動かす例&quot;">​</a></h2><p>図では、前の仕事を待つ時間が3 msあるため、描画完了は17 msです。仮想ディスプレイの次の走査は33.33 msから始まり、画面中央には41.67 msで届きます。入力が届いた7 msから数えると <strong>34.67 ms</strong> です。</p><p>同じ条件でGPUの待ちだけを1 msに減らすと、描画完了は15 msです。16.67 msの走査に間に合い、中央の表示時刻は25 ms、入力からの遅延は <strong>18.00 ms</strong> になります。仕事を2 ms早く始めたことで一つ前の走査に入るため、この例では表示が約16.67 ms早まります。走査に間に合うかどうかで、処理時間の改善量と表示時刻の変化量は異なります。<a href="/study/practice/graphics/input-latency-observation.html">待ち時間を変えて試す</a></p><h2 id="実機では測る範囲をそろえる" tabindex="-1">実機では測る範囲をそろえる <a class="header-anchor" href="#実機では測る範囲をそろえる" aria-label="Permalink to &quot;実機では測る範囲をそろえる&quot;">​</a></h2><ol><li><strong>何に反応させるかを決める。</strong> 例えばボタンを押すと、毎回同じ位置の四角が白くなる場面を作ります。測定対象の入力に番号を付け、同じ入力で変わったフレームを追います。</li><li><strong>ゲーム内の区間を分ける。</strong> 入力取得、シミュレーション更新、描画の提出にマーカーを置きます。GPUの開始・完了と提示も記録し、時間が延びた箇所の前後を比べます。CPUとGPUの時刻を並べるときは、プロファイラの統合された時間軸か、校正されたタイムスタンプを使います。<a href="https://learn.microsoft.com/en-us/windows/pix/timing-captures/timing-captures-overview" target="_blank" rel="noreferrer">MicrosoftのPIX Timing Captures</a></li><li><strong>機器込みの遅延を測る。</strong> 物理入力と光の変化が分かる治具や、入力の目印と画面の対象を同時に撮る高速度カメラを使います。撮影で数える場合は、撮影フレーム間隔の分だけ時刻の分解能が限られます。画面位置、表示設定、入力機器をそろえて複数回測り、中央値とばらつきを比べます。<a href="https://www.nvidia.com/en-us/geforce/news/reflex-latency-analyzer-360hz-g-sync-monitors/" target="_blank" rel="noreferrer">NVIDIAの入力機器・PC・画面を含む測定例</a></li></ol><p>DXGIの待機可能なスワップチェーンで、フレームを受け付けられるまで待ってから最新の入力を読む方法があります。対策を入れたら、入力が使われるまでの待ちと、表示間隔のばらつきの両方を確認します。<a href="https://learn.microsoft.com/en-us/windows/uwp/gaming/reduce-latency-with-dxgi-1-3-swap-chains" target="_blank" rel="noreferrer">MicrosoftのDXGI遅延低減手順</a> · <a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a></p>',12)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
